  from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "tc-al-adopt-1", "state": "AL", "tier": "core", "title": "Alabama traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Alabama: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: All flaggers must complete the ATSSA Flagger Training course before beginning work; completion records kept on file (quoted from an ALDOT debris-removal contract document, not the general standard specifications). Accepted: ATSSA course. (ALDOT Contractual Documents ... Debris Removal (as reproduced by the Work Zone Safety Information Clearinghouse).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-01-16; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "ALDOT Contractual Documents ... Debris Removal (as reproduced by the Work Zone Safety Information Clearinghouse); adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-40/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "ALDOT Contractual Documents ... Debris Removal (as reproduced by the Work Zone Safety Information Clearinghouse), as posted 2025-01-16", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched ALDOT for an 11th Edition adoption memo; found only ALDOT special drawings revised 11-19-2025 for 11th Edition sign numbers."}},
{"lib": "field", "chunk": {"id": "tc-ak-adopt-1", "state": "AK", "tier": "core", "title": "Alaska traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Alaska uses the Alaska Traffic Manual: the national MUTCD 11th Edition (December 2023) plus the 2026 Alaska Traffic Manual Supplement (ATMS), effective January 20, 2026. The ATMS changes Part 6: on state highways flaggers must be certified under Standard Specification Section 643 (6D.01), the STOP/SLOW paddle is 24 inches with 8 inch letters except on local roads of 25 mph or less (6D.02), and Alaska has its own sign spacing table (6B-1). Flaggers: Flaggers must hold a current certification from the DOT&PF list. How long it lasts: current (period not stated). Accepted: IMSA Flagging Level I; ATSSA Flagger Certification; ATSSA Traffic Control Supervisor; IMSA Work Zone Safety Specialist; ATSSA Flagging Instructor. (Alaska DOT&PF Standard Specifications for Highway Construction, Flagging provision.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers and spacing follow the national MUTCD Part 6 unless the state manual or permit says otherwise. The approved traffic control plan governs.", "source": "Alaska DOT&PF 2026 Alaska Traffic Manual Supplement (ATMS) Rev. 0, Sections 6B.01, 6D.01, 6D.02, Table 6B-1; Chief Engineer directive Mar. 13, 2026", "url": "https://dot.alaska.gov/stwddes/dcstraffic/assets/pdf/atm/current/2026_atm.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2026 Alaska Traffic Manual Supplement, Revision 0", "effective": "2026-01-20"}},
{"lib": "field", "chunk": {"id": "tc-az-adopt-1", "state": "AZ", "tier": "core", "title": "Arizona traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Arizona uses the national MUTCD 11th Edition together with the Arizona Supplement to the MUTCD (ADOT, January 2026). In Part 6 the supplement changes only Section 6A.02, Section 6G.08 (double fine signs) and the entrance ramp drawing TA-44; tapers, sign spacing and flagger rules are the national ones. Flagger card rule: not confirmed for Arizona from a state source read here. The national MUTCD says flaggers should be trained (Section 6D.01); ask ADOT or the city that issued the permit which flagger course it accepts. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "ADOT Arizona Supplement to the MUTCD 11th Edition (January 2026), Sections 6A.02, 6G.08, Figure 6P-44AZ", "url": "https://azdot.gov/sites/default/files/2026-02/Arizona-Supplement-MUTCD.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Arizona Supplement to the MUTCD 11th Edition, January 2026", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ar-adopt-1", "state": "AR", "tier": "core", "title": "Arkansas traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Arkansas: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: All flaggers must be trained prior to starting work in the field (ARDOT employee Safety Manual; contractor rule not confirmed). (ARDOT Safety Manual, Flagger Training.) Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "ARDOT Safety Manual, Flagger Training; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-9/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "ARDOT Safety Manual, Flagger Training, as posted 2024-01-30", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched ARDOT / Highway Commission minute orders (2024-2026) and standard drawing TC-2 (rev. 08-14-25); none states 11th Edition adoption."}},
{"lib": "field", "chunk": {"id": "tc-ca-adopt-1", "state": "CA", "tier": "core", "title": "California traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "California uses its own manual, the California MUTCD (CA MUTCD). The current one is the CA MUTCD 2026, issued by Caltrans effective January 18, 2026 under Vehicle Code 21400; it replaced the CA MUTCD 2014 Revision 9 and is written to substantially conform to the national 11th Edition. Flaggers: the CA MUTCD makes training a requirement. Flaggers shall be trained in the fundamentals of flagging moving traffic before they are assigned (Section 6D.01, a California Standard), following Cal/OSHA Construction Safety Orders section 1599, with training records kept under the employer's Injury and Illness Prevention Program (8 CCR 3203). The state does not issue a flagger card. California prints its own tables: sign spacing by speed in Table 6B-1 and 12 ft taper lengths in Table 6B-3(CA) of the CA MUTCD; the taper formula is the national one, L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan or encroachment permit governs.", "source": "Caltrans CA MUTCD 2026 page (effective Jan. 18, 2026); CA MUTCD 2026 Chapters 6B, 6C, 6D", "url": "https://dot.ca.gov/programs/safety-programs/camutcd", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-co-adopt-1", "state": "CO", "tier": "core", "title": "Colorado traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Colorado uses the national MUTCD 11th Edition with the Colorado State Supplement, effective January 18, 2026 (adopted by the Transportation Commission December 17, 2025; mandatory under C.R.S. 42-4-104 and 42-4-105). The supplement's Part 6 changes are small: a STOP/SLOW paddle at least 18 inches wide with 6 inch letters, an added flashlight signal, and temporary pavement marker spacing. Flaggers: To get or renew CDOT flagger certification: at least 18, trained by a CDOT-authorized entity, pass a closed-book exam; flaggers must speak and understand English (Jan 2026 memo); fluorescent red apparel not allowed for flaggers in Colorado. Accepted: CDOT flagger card. (CDOT Flagger Program FAQs; CDOT Flagger Program industry memo January 2026.) Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "CDOT Colorado State Supplement to the MUTCD 11th Edition (Jan. 2026), Sections 6D.03, 6D.04; CDOT Flagger Program memo Jan. 2026", "url": "https://www.codot.gov/safety/traffic-safety/assets/documents/mutcd/colorado-supplement-mutcd_final-12302025.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Colorado State Supplement, January 2026", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-ct-adopt-1", "state": "CT", "tier": "core", "title": "Connecticut traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Connecticut: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Uniformed flaggers must have successfully completed flagger training by ATSSA, the National Safety Council, or other training approved by the Engineer; certificate to the Engineer before work. Accepted: ATSSA, NSC, or Engineer-approved. (CTDOT Standard Specifications Form 819 (2024), Uniformed Flagger.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-02-13; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "CTDOT Standard Specifications Form 819 (2024), Uniformed Flagger; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-21/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "CTDOT Standard Specifications Form 819 (2024), Uniformed Flagger, as posted 2025-02-13", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Read CTDOT OSTA page (names the MUTCD, no edition) and the regs index for 14-298; adopting text not reached."}},
{"lib": "field", "chunk": {"id": "tc-de-adopt-1", "state": "DE", "tier": "core", "title": "Delaware traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Delaware uses its own manual, the Delaware MUTCD. DelDOT's page lists the 2011 Delaware MUTCD (built on the 2009 national edition; Part 6 published December 2012) as the operative manual, with a 2026 Delaware MUTCD marked pending approval. Whether the 2026 edition has taken effect is not confirmed; check the DelDOT Delaware MUTCD page. Flaggers: Flaggers on state-maintained roadways must be certified by a DelDOT-recognized program and carry the flagger certification card and photo ID. Accepted: ATSSA (classroom or online), OnlineFlagger.com, LIUNA Work Zone Safety Program. (Delaware MUTCD Section 6E.01 Standard (DE revision); DelDOT memo Acceptable Flagger Certification (11/01/2016).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "DelDOT Delaware MUTCD page (2011 DE MUTCD; 2026 pending); DelDOT memo Acceptable Flagger Certification (11/01/2016)", "url": "https://www.deldot.gov/Publications/manuals/de_mutcd/index.shtml", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2011 Delaware MUTCD (2026 edition pending approval)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-dc-adopt-1", "state": "DC", "tier": "core", "title": "District of Columbia traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "District of Columbia: which MUTCD edition DDOT has in force was not confirmed here; ask DDOT's public space permit office. Flaggers: Flaggers shall be certified by ATSSA or another agency approved by the Engineer. Accepted: ATSSA or Engineer-approved. (DDOT Standard Specifications for Highways and Structures (2013), Flagger Certification.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "DDOT Standard Specifications for Highways and Structures (2013), Flagger Certification; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "DDOT Standard Specifications for Highways and Structures (2013), Flagger Certification, as posted 2022-08-02", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched DDOT; found only the 2006 DDOT Work Zone TTC Manual and TCP submittal guidelines; no 11th Edition adoption notice."}},
{"lib": "field", "chunk": {"id": "tc-fl-adopt-1", "state": "FL", "tier": "core", "title": "Florida traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Florida adopts the national MUTCD by rule: Rule 14-15.010, Florida Administrative Code, adopts the FHWA MUTCD 11th Edition (December 2023), effective January 1, 2025, under section 316.0745, Florida Statutes. FDOT's page says the most current version is the 11th Edition with Revision 1. Flagger card rule: not confirmed for Florida from a state source read here. The national MUTCD says flaggers should be trained (Section 6D.01); FDOT runs a Temporary Traffic Control (MOT) training program with a flagger course, so ask FDOT or the permit office which card it wants. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "Fla. Admin. Code R. 14-15.010 (eff. 1/1/2025); s. 316.0745, Fla. Stat.; FDOT MUTCD page", "url": "https://www.law.cornell.edu/regulations/florida/Fla-Admin-Code-Ann-R-14-15-010", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition (December 2023) as adopted by Rule 14-15.010", "effective": "2025-01-01", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ga-adopt-1", "state": "GA", "tier": "core", "title": "Georgia traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Georgia uses the national MUTCD. The State Transportation Board approved the 11th Edition on June 20, 2024, and GDOT's Chief Engineer memo of September 18, 2024 puts projects let after January 2025 under it. Flaggers: Flaggers on the State Highway System need training and a certificate, for contract or permit work (utilities included); work can be suspended without a certified flagger. Accepted: ATSSA or National Safety Council programs. (GDOT Certifications & Training website.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-01-31; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "GDOT Chief Engineer memo, 11th Edition MUTCD (Sept. 18, 2024); GDOT Certifications & Training", "url": "https://www.dot.ga.gov/PartnerSmart/DesignManuals/PolicyAnnouncements/Chief%20Engineer%20Memo%2011th%20edition%20MUTCD.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition, adopted June 20, 2024", "effective": "2024-06-20"}},
{"lib": "field", "chunk": {"id": "tc-hi-adopt-1", "state": "HI", "tier": "core", "title": "Hawaii traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Hawaii: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Nationally recognized Work Zone Traffic Control Safety - Flagger training and certification meeting MUTCD (quoted from one HDOT Highways Division contract addendum, Island of Hawaii). How long it lasts: certification completed within a maximum of 4 years. (HDOT Highways Division contract addendum (as reproduced by the Clearinghouse).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "HDOT Highways Division contract addendum (as reproduced by the Clearinghouse); adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-49/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "HDOT Highways Division contract addendum (as reproduced by the Clearinghouse), as posted 2022-08-02", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched HDOT administrative rules (Title 19) and HDOT highways pages; no 11th Edition adoption found."}},
{"lib": "field", "chunk": {"id": "tc-id-adopt-1", "state": "ID", "tier": "core", "title": "Idaho traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Idaho adopts the national MUTCD with Idaho additions by rule (IDAPA 39.03.41). The rule copy read here (effective March 31, 2022) still names the 2009 edition; ITD ran a rulemaking in 2024 to adopt the 11th Edition, but the date it took effect was not confirmed. ITD also publishes a Traffic Manual as Idaho's supplementary guide; ask ITD Traffic which edition applies. Flaggers: Flagger certification from an ITD-approved course by an ITD-approved instructor (Evergreen Safety Council and ATSSA courses approved); ITD accepts Washington, Oregon and Montana cards under a multi-state agreement, and Utah under a separate agreement. Accepted: ITD-approved, WA, OR, MT, UT. (Idaho Transportation Department, Flagger and Traffic Control Supervisor Certification and Reciprocity Information.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2026-01-23; confirm it in the current spec book before you rely on it. Tapers and spacing follow the national MUTCD Part 6 unless the state manual or permit says otherwise. The approved traffic control plan governs.", "source": "IDAPA 39.03.41.004 (eff. 3/31/2022, Justia copy current through 6/4/2025); ITD rulemaking change summary (July 3, 2024)", "url": "https://regulations.justia.com/states/idaho/39/39-03-41/section-39-03-41-004/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "IDAPA 39.03.41 (copy read names the 2009 MUTCD)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-il-adopt-1", "state": "IL", "tier": "core", "title": "Illinois traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Illinois uses the national MUTCD 11th Edition with the Illinois Supplement to the MUTCD, 11th Edition (IDOT, February 2026). In Part 6 the supplement adds only three items: contractors and permit holders stay responsible for placing, keeping up and operating their traffic control devices (6A.01), weight limit signing (6G.06), and short-term pavement markings under IDOT policy TRA-17 (6J.02). Tapers, sign spacing and flagger procedures are the national ones. Flaggers: All flaggers shall be certified by an agency approved by the Department. Accepted: ATSSA, National Safety Council, Illinois Laborers' & Contractors' Joint Apprenticeship Program (contract and permit work). (IDOT Standard Specifications Section 701.13.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-01-16; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "IDOT Illinois Supplement to the MUTCD, 11th Edition (Feb. 2026), Sections 6A.01, 6G.06, 6J.02", "url": "https://public.powerdms.com/IDOT/documents/2010838/Illinois%20Supplement%20to%20the%20Manual%20on%20Uniform%20Traffic%20Control%20Devices%2C%20Revision%203", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Illinois Supplement to the MUTCD 11th Edition, February 2026"}},
{"lib": "field", "chunk": {"id": "tc-in-adopt-1", "state": "IN", "tier": "core", "title": "Indiana traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Indiana uses its own manual, the Indiana MUTCD (IMUTCD). The 2025 Indiana MUTCD, built on the national 11th Edition, became effective January 16, 2026 (Indiana Code 9-21-2). Flaggers: Flagging supervised by a certified worksite traffic supervisor or a flagger certified by ATSSA or approved equal; supervisor ensures flaggers are trained. (INDOT Standard Specifications (references 107.12).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "INDOT 2025 Indiana MUTCD page (effective Jan. 16, 2026); INDOT Standard Specifications", "url": "https://www.in.gov/indot/doing-business-with-indot/consultants/designers/indiana-manual-on-uniform-traffic-control-devices-mutcd/2025-indiana-manual-on-uniform-traffic-control-devices", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2025 Indiana MUTCD", "effective": "2026-01-16"}},
{"lib": "field", "chunk": {"id": "tc-ia-adopt-1", "state": "IA", "tier": "core", "title": "Iowa traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Iowa uses the national MUTCD 11th Edition (December 2023) as adopted by Iowa Administrative Code rule 761-130.1, effective April 22, 2026. There is no separate Iowa supplement: the rule makes only two Part 2 sign exceptions and none in Part 6, so work zone tapers, sign spacing and flagger procedures are the national ones. Flaggers: Flaggers trained before flagging (Iowa DOT flagger materials, MUTCD Part 6); employer issues a flagger training card; not required for short time, emergency or relief assignment. How long it lasts: card expires December 31 of the year after the training date. Accepted: Iowa DOT flagger training card issued by the employer. (Iowa DOT Standard Specifications Section 2528.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-09-30; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "Iowa Admin. Code 761-130.1 (ARC 0149D, IAB 3/18/26, eff. 4/22/26)", "url": "https://www.legis.iowa.gov/docs/iac/chapter/03-18-2026.761.130.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition (December 2023) via 761 IAC 130.1", "effective": "2026-04-22"}},
{"lib": "field", "chunk": {"id": "tc-ks-adopt-1", "state": "KS", "tier": "core", "title": "Kansas traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Kansas law (K.S.A. 8-2003) has the Secretary of Transportation adopt a manual that conforms as far as possible to the most recent national MUTCD. A September 2024 Kansas Register notice shows KDOT reviewing the 11th Edition with FHWA approval targeted by December 12, 2025, but the adoption itself was not confirmed; ask KDOT which edition applies. Flaggers: Flaggers trained in MUTCD Part 6 flagger procedures and the KDOT Flagger Handbook; carry a card with name and training date. How long it lasts: retrain every 3 years. (KDOT Standard Specifications, Flaggers.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-04-11; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "K.S.A. 8-2003; Kansas Register Vol. 43 No. 37 (Sept. 12, 2024), KDOT consultant notice", "url": "https://ksrevisor.gov/statutes/chapters/ch08/008_020_0003.html", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "K.S.A. 8-2003 as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ky-adopt-1", "state": "KY", "tier": "core", "title": "Kentucky traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Kentucky uses the national MUTCD 11th Edition (December 2023), incorporated by reference in 603 KAR 5:050, effective February 18, 2025. The regulation makes no Part 6 changes, so work zone tapers, sign spacing and flagger procedures are the national ones. Flaggers: All flaggers trained in current MUTCD flagging procedures; proof available. How long it lasts: credentials current within the last 5 years. (KYTC Standard Specifications Section 112.03.01.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-09-08; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "603 KAR 5:050 Section 3(1) (51 Ky.R. 785; eff. 2-18-2025)", "url": "https://apps.legislature.ky.gov/law/kar/titles/603/005/050/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition via 603 KAR 5:050", "effective": "2025-02-18"}},
{"lib": "field", "chunk": {"id": "tc-la-adopt-1", "state": "LA", "tier": "core", "title": "Louisiana traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Louisiana: DOTD's traffic engineering manuals page posts an Authorization for 11th Edition MUTCD memo and a January 2026 Traffic Engineering Manual. The memo could not be opened here, so the date the 11th Edition took effect in Louisiana is not confirmed. Temporary traffic control standard plans are on DOTD's Standard Plans page. Flaggers: All flaggers shall be qualified (ATSSA-type course or a course approved by the LADOTD Work Zone Task Force). Accepted: ATSSA-type or approved course. (LADOTD Temporary Traffic Control General Notes sheet (02-07-2025).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2026-04-10; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "LA DOTD Traffic Engineering Manuals and Policies page", "url": "https://dotd.la.gov/about/office-of-engineering/traffic-engineering/manuals-and-policies/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "LA DOTD manuals page as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-me-adopt-1", "state": "ME", "tier": "core", "title": "Maine traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Maine: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Flagger certification required on MaineDOT state/federal-funded projects; state law since 1991 requires privately employed flaggers to have MUTCD-consistent training. (MaineDOT Specification 652.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-06-25; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MaineDOT Specification 652; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-13/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MaineDOT Specification 652, as posted 2025-06-25", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-md-adopt-1", "state": "MD", "tier": "core", "title": "Maryland traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Maryland uses its own manual, the Maryland MUTCD (MdMUTCD). MDOT SHA's page still lists the 2011 MdMUTCD (the 2009 national edition plus Maryland's changes) as current, with FHWA-approved revisions through March 13, 2023; in that edition the flagger rules are Chapter 6E. An 11th Edition MdMUTCD was not found posted, so whether one has taken effect is not confirmed; check with MDOT SHA. Flaggers: Flaggers must complete the SHA or ATSSA flagger course before working in Maryland work zones (flagger card); emergency: non-approved flagger up to 15 minutes. Accepted: SHA or ATSSA flagger card. (Maryland SHA Frequently Asked Work Zone Questions.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2023-05-15; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MDOT SHA Maryland MUTCD 2011 Edition page (revisions through Mar. 13, 2023)", "url": "https://roads.maryland.gov/mdotsha/pages/Index.aspx?PageId=835", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2011 MdMUTCD (11th Edition MdMUTCD not found)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ma-adopt-1", "state": "MA", "tier": "core", "title": "Massachusetts traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Massachusetts uses the national MUTCD 11th Edition with the Massachusetts Amendments (January 2026), formally adopted by MassDOT Policy Directive P-26-003 dated March 2, 2026 (effective at once; MassDOT projects advertised after March 7, 2026). In Part 6 the amendments require flaggers on public roads to be certified by MassDOT (6D.01), cones at least 36 inches tall (6K.01), and an airhorn for every flagger, with two-way radios when two or more flaggers work together (6D.05, 6D.06). Flaggers: MassDOT flagger certification: first aid/CPR, work zone safety and flagger training, 50-question exam passed at 80%. How long it lasts: 2 years. Accepted: NSC, ATSSA, OSHA Training Institute or equivalent approved program. (MassDOT flagger certification program; 701 CMR 7.07(2).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-12-23; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MassDOT Policy Directive P-26-003 (Mar. 2, 2026); Massachusetts Amendments to the MUTCD 11th Edition (Jan. 2026), Sections 6D.01, 6D.05, 6D.06, 6K.01", "url": "https://www.mass.gov/doc/massachusetts-amendments-to-the-11th-edition-of-the-manual-on-uniform-traffic-control-devices-2026/download", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Massachusetts Amendments to the MUTCD 11th Edition, January 2026", "effective": "2026-03-02"}},
{"lib": "field", "chunk": {"id": "tc-mi-adopt-1", "state": "MI", "tier": "core", "title": "Michigan traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Michigan uses its own manual, the Michigan MUTCD (MMUTCD), adopted jointly by MDOT and the Michigan State Police. The 2025 MMUTCD, built on the national 11th Edition, was published January 15, 2026 (MDOT presentation, February 2026); its effective date and Part 6 changes were not confirmed here. Michigan calls flaggers traffic regulators. Flaggers: Traffic regulators must complete traffic regulator training (state video + MDOT Traffic Regulator's Instruction Manual). How long it lasts: training no more than 12 months before regulating traffic. (MDOT Work Zone Safety and Mobility Manual Section 1.05.03.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-03-21; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MDOT presentation \"MMUTCD Update\", Michigan Tech CTT County Engineers Workshop (Feb. 3, 2026)", "url": "https://ctt.mtu.edu/sites/ctt/files/resources/cew/2026/1.08a_MMUTCD_Update_CEW%20Muskegon_2026.02.03.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2025 Michigan MUTCD", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-mn-adopt-1", "state": "MN", "tier": "core", "title": "Minnesota traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Minnesota uses its own manual, the Minnesota MUTCD (MN MUTCD) 11th Edition, based on the national MUTCD. The Commissioner of Transportation adopted it effective January 18, 2026; new or reconstructed traffic control devices must comply from that date (MnDOT, November 2025). MnDOT also publishes a Temporary Traffic Control Zone Layouts Field Manual for short jobs. Flaggers: Flaggers and pilot drivers must attend training by a MnDOT-qualified flagger trainer; Flagger Qualification Card or checklist to the Engineer. (MnDOT Special Provisions Section I.1 (trunk highway projects).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MnDOT E-Scene, \"MnDOT publishes 11th Edition of the MN MUTCD\" (Nov. 2025); MnDOT Special Provisions Section I.1, Flagging Operations", "url": "https://www.dot.state.mn.us/stateaid/scene/2025/11/mnmutcd.html", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Minnesota MUTCD 11th Edition", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-ms-adopt-1", "state": "MS", "tier": "core", "title": "Mississippi traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Mississippi: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Flaggers must have proof of certification and ID while flagging. How long it lasts: recertify every 4 years. Accepted: ATSSA; MDOT-recognized industry association training; MDOT training. (MDOT Standard Specifications.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MDOT Standard Specifications; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-36/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MDOT Standard Specifications, as posted 2022-08-02", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched MDOT and Miss. Code 63-3-301; MDOT rules only say \"MUTCD, Current Edition\"."}},
{"lib": "field", "chunk": {"id": "tc-mo-adopt-1", "state": "MO", "tier": "core", "title": "Missouri traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Missouri's work zone rules are in MoDOT's Engineering Policy Guide, Article 616 (Temporary Traffic Control), now arranged by the 11th Edition chapters 6A to 6P (616.4 Flagger Control is MUTCD Chapter 6D). The date Missouri formally adopted the 11th Edition was not confirmed. Since July 1, 2026, MoDOT or contractor vehicles may run a rolling roadblock, and every protective vehicle in the lane needs a truck-mounted attenuator (EPG 616.19.7). Flaggers: Valid flagger certification card (training by a qualified person in flagging and MUTCD Chapter 6), given to the engineer before flagging. How long it lasts: recertify at least every 4 years. (MoDOT Standard Specifications Section 616.4.3.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MoDOT EPG Category 616 (edited May 1, 2026); MoDOT General Letter G-2026-07 (eff. July 1, 2026), EPG 616.19.7", "url": "https://epg.modot.org/index.php/Category:616_Temporary_Traffic_Control", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MoDOT EPG Article 616 (May 2026)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-mt-adopt-1", "state": "MT", "tier": "core", "title": "Montana traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Montana adopted the national MUTCD 11th Edition in its entirety, with no state supplement, effective January 1, 2026 (MDT design memo, October 22, 2024). Temporary traffic control devices on MDT projects had to comply by that date. Tapers, sign spacing and flagger procedures are the national ones. Flaggers: Flaggers currently certified through the Montana flagger program, ATSSA, or the Idaho, Oregon or Washington programs; carry proof. Accepted: Montana, ATSSA, Idaho, Oregon, Washington. (MDT Standard Specifications Section 618.03.14.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-03-07; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MDT 11th Edition MUTCD Design Memo (Oct. 22, 2024)", "url": "https://www.mdt.mt.gov/other/webdata/external/Traffic/design_memos/2024-10-22-11th-Edition-MUTCD-Design-Memo.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition, adopted without supplement", "effective": "2026-01-01"}},
{"lib": "field", "chunk": {"id": "tc-ne-adopt-1", "state": "NE", "tier": "core", "title": "Nebraska traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Nebraska uses the national MUTCD 11th Edition with the Nebraska 2025 Supplement to the MUTCD (NDOT). The supplement's Part 6 has only an addendum to the typical applications (6H.01); no change to tapers, sign spacing or flagger procedures was found. NDOT's page does not state an effective date. Flaggers: Only certified flaggers may flag except emergencies or situations under 15 minutes; view The Flagger video and pass exam at 80%; contractor trains/certifies; carry card and Flagger's Handbook. Accepted: unexpired cards issued by other contractors accepted. (Nebraska Standard Specifications Section 422 para 12.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-08-27; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "NDOT MUTCD page; Nebraska Supplement to the MUTCD (2025), Section 6H.01", "url": "https://dot.nebraska.gov/business-center/contractor/mutcd/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition with Nebraska 2025 Supplement"}},
{"lib": "field", "chunk": {"id": "tc-nv-adopt-1", "state": "NV", "tier": "core", "title": "Nevada traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Nevada law has the Department of Transportation adopt the manual for traffic control devices, and every device used by the state or a local agency must conform to it (NRS 484A.430). Which MUTCD edition NDOT has in force today was not confirmed from an NDOT page; ask the NDOT district or the city or county that issues the permit. Flaggers: Flaggers shall have completed an approved instructional course in flagger procedures; valid flagger card from NDOT course or NDOT-approved course. Accepted: NDOT or NDOT-approved course card. (NDOT Standard Specifications for Road and Bridge Construction.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-03-21; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "NRS 484A.430; NDOT Standard Specifications for Road and Bridge Construction, Flaggers", "url": "https://nevada.public.law/statutes/nrs_484A.430", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "NRS 484A.430 as read 2026-11-20", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched NDOT traffic and standard plans pages; no 11th Edition adoption statement found."}},
{"lib": "field", "chunk": {"id": "tc-nh-adopt-1", "state": "NH", "tier": "core", "title": "New Hampshire traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "New Hampshire: an industry tracker lists the state as one that uses the national MUTCD with a state supplement, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flagger card rule: not confirmed for New Hampshire. The national MUTCD only says flaggers should be trained (Section 6D.01); ask the state DOT or the agency that issued the permit which flagger course it accepts. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "MUTCD 11th Edition Section 6D.01 (national); adoption status not confirmed", "url": "https://mutcd.fhwa.dot.gov/resources/state_info/index.htm", "checked": "2026-11-20", "confidence": "low", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition, December 2023 (state status not confirmed)", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched NHDOT; found the work zone safety and mobility manual and TODS rules, no 11th Edition adoption."}},
{"lib": "field", "chunk": {"id": "tc-nj-adopt-1", "state": "NJ", "tier": "core", "title": "New Jersey traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "New Jersey: NJDOT's courtesy copy of its traffic control rule (N.J.A.C. 16:27-2.1) still defines the MUTCD as the 2009 edition, as amended and supplemented. Adoption of the 11th Edition was not confirmed from NJDOT; ask NJDOT or the permit office which edition applies. Flagger card rule: not confirmed for New Jersey. The national MUTCD only says flaggers should be trained (Section 6D.01); ask the state DOT or the agency that issued the permit which flagger course it accepts. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "N.J.A.C. 16:27-2.1 (NJDOT courtesy copy)", "url": "https://nj.gov/transportation/about/rules/documents/16-27-Current.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "N.J.A.C. 16:27 (names the 2009 MUTCD)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-nm-adopt-1", "state": "NM", "tier": "core", "title": "New Mexico traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "New Mexico: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Contractor submits flagger training card before flagger work. How long it lasts: 4 years. Accepted: ATSSA, ACNM, FHWA, or Department-approved. (NMDOT Standard Specifications Sections 618.2.1, 618.2.1.1.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2024-10-17; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "NMDOT Standard Specifications Sections 618.2.1, 618.2.1.1; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-42/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "NMDOT Standard Specifications Sections 618.2.1, 618.2.1.1, as posted 2024-10-17", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched NMDOT and NMAC Title 18; no 11th Edition adoption found."}},
{"lib": "field", "chunk": {"id": "tc-ny-adopt-1", "state": "NY", "tier": "core", "title": "New York traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "New York uses the national MUTCD together with the New York State Supplement (17 NYCRR Chapter V). As of June 2026 NYSDOT was preparing a rulemaking to revise the State Supplement (APWA New York chapter notice, June 5, 2026); whether the 11th Edition and a new supplement are in force is not confirmed. Check the NYSDOT MUTCD page. Flaggers: Flaggers adequately trained by recognized programs (ATSSA, NSC, unions, construction industry associations) or by a certified flagger instructor; roster of credentialed flaggers to the Engineer. (NYSDOT Standard Specifications (2025), Flagger Training.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2024-10-22; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "17 NYCRR Chapter V (NYS Supplement); APWA New York chapter notice (June 5, 2026); NYSDOT Standard Specifications (2025), Flagger Training", "url": "https://newyork.apwa.org/?p=1066", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "17 NYCRR Chapter V (revision in rulemaking, June 2026)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-nc-adopt-1", "state": "NC", "tier": "core", "title": "North Carolina traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "North Carolina: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: All personnel flagging, spotting or operating AFADs must complete an NCDOT-approved flagger course. (NCDOT Work Zone Safety Qualification and Training Program.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "NCDOT Work Zone Safety Qualification and Training Program; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-14/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "NCDOT Work Zone Safety Qualification and Training Program, as posted 2022-08-02", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-nd-adopt-1", "state": "ND", "tier": "core", "title": "North Dakota traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "North Dakota: NDDOT says it has adopted the 2023 MUTCD (11th Edition) (NDDOT Traffic Operations Manual, January 2026). That manual does not give the adoption date or list state changes, so treat the national Part 6 as the rule unless the contract or permit says otherwise. Flaggers: Pass a written examination (ndsc.org) before flagging; written verification to the Engineer. (NDDOT Standard Specifications (2025), Flaggers.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-08-28; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "NDDOT Traffic Operations Manual (Jan. 2026)", "url": "https://www.dot.nd.gov/sites/www/files/documents/construction-and-planning/Traffic-Operations-Manual.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition (NDDOT Traffic Operations Manual, January 2026)"}},
{"lib": "field", "chunk": {"id": "tc-oh-adopt-1", "state": "OH", "tier": "core", "title": "Ohio traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Ohio uses the national MUTCD 11th Edition with the Ohio Supplement to the MUTCD, effective January 16, 2026 (Ohio Revised Code 4511.09); a July 17, 2026 printing is posted. The supplement's contents list changes to Part 6, including Section 6B.08 and Table 6B-3 on tapers; those Ohio taper values were not confirmed here, so read the supplement before using a taper length. Flaggers: Ohio does not require flagger certification or registration (flaggers should be trained). (Ohio LTAP, Flagging Operations on 2-lane Rural Roads.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "ODOT Ohio Supplement to the MUTCD 11th Edition (eff. Jan. 16, 2026; July 17, 2026 printing); ORC 4511.09", "url": "https://dam.assets.ohio.gov/image/upload/transportation.ohio.gov/traffic/ohio-supp-mutcd/20260717_Ohio_Supplement.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Ohio Supplement to the MUTCD 11th Edition", "effective": "2026-01-16", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ok-adopt-1", "state": "OK", "tier": "core", "title": "Oklahoma traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Oklahoma: ODOT's site lists an Oklahoma 2009 MUTCD Supplement, and no 11th Edition supplement or adoption notice was found, so the edition in force is not confirmed. Ask ODOT Traffic Engineering which edition applies. Flaggers: A flagger should be trained in safe traffic control practices and public contact techniques (guideline; no card rule found). (ODOT Guidelines for Temporary Traffic Control.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "ODOT Oklahoma 2009 MUTCD Supplement (listed); adoption status not confirmed", "url": "https://oklahoma.gov/content/dam/ok/en/odot/documents/traffic/oklahoma-2009-mutcd-supplement.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Oklahoma 2009 MUTCD Supplement (11th Edition status not confirmed)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-or-adopt-1", "state": "OR", "tier": "core", "title": "Oregon traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Oregon uses the national MUTCD 11th Edition with the Oregon Supplement (ODOT, January 2026), adopted in OAR 734-020-0005 and effective January 1, 2026. The supplement makes no numbered changes to Part 6; instead, work zones in place 3 days or less follow the Oregon Temporary Traffic Control Handbook (OTTCH), 2026 edition. Flaggers: Flaggers must have completed an approved flagging course within the past 3 years and hold a current card; Oregon, Washington, Idaho or Montana certification accepted; age 18+. How long it lasts: 3 years. Accepted: OR, WA, ID, MT. (ODOT Standard Specifications 00223.30; Oregon Temporary Traffic Control Handbook 2026 sections 3.2-3.3.) Taper, cone and sign spacing tables for short jobs are in the handbook (Tables 2-1 to 2-4); the taper formula is the national one. The approved traffic control plan governs.", "source": "ODOT Oregon Supplement to the MUTCD 11th Edition (Jan. 2026); OAR 734-020-0005; OTTCH 2026 sections 1.1, 3.2", "url": "https://www.oregon.gov/odot/Get-Involved/OTCDC/MUTCD11-OR-Supplement.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "Oregon Supplement to the MUTCD 11th Edition, January 2026", "effective": "2026-01-01"}},
{"lib": "field", "chunk": {"id": "tc-pa-adopt-1", "state": "PA", "tier": "core", "title": "Pennsylvania traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Pennsylvania adopts the national MUTCD through 67 Pa. Code 212.2, except where Chapter 212 says otherwise. A PennDOT LTAP sheet (May 2026) says the 11th Edition adoption was made effective by a Pennsylvania Bulletin notice in January 2026; the exact day was not confirmed. PennDOT's work zone drawings are Publication 213, edition 2022-04. Flaggers: Flaggers must have completed a flagger training course meeting PennDOT minimum guidelines within the last 3 years; wallet card or roster. How long it lasts: 3 years. (PennDOT Publication 408/2020, Flagger Training.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-06-24; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "PennDOT LTAP MUTCD sheet (May 2026); 67 Pa. Code 212.2; PennDOT Publication 408/2020, Flagger Training", "url": "https://gis.penndot.pa.gov/BPR_PDF_FILES/Documents/LTap/MUTCD_Drop_In_May_2026.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition via 67 Pa. Code Chapter 212; Publication 213 (2022-04)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ri-adopt-1", "state": "RI", "tier": "core", "title": "Rhode Island traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Rhode Island: the State Traffic Commission rule (550-RICR-00-00-1, Section 1.3, current version effective January 4, 2022) still incorporates the MUTCD as the 2009 edition. Adoption of the 11th Edition was not confirmed from a state source; ask RIDOT's traffic office which edition applies. Flaggers: Certificate from a RIDOT-approved course; know the FHWA flagging handbook. Accepted: National Safety Council, ATSSA, N.E. Laborers Union Training Academy. (RIDOT Standard Specifications Section 914.02.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2024-03-21; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "550-RICR-00-00-1 Section 1.3 (eff. 01/04/2022)", "url": "https://rules.sos.ri.gov/regulations/part/550-00-00-1", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "550-RICR-00-00-1 (names the 2009 MUTCD)", "effective": "2022-01-04", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-sc-adopt-1", "state": "SC", "tier": "core", "title": "South Carolina traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "South Carolina: which MUTCD edition SCDOT has in force was not confirmed from SCDOT. SCDOT's work zone page posts a Flaggers Handbook (2026, a pocket guide to flagging) and Work Zone Safety Guidelines (2026) for short-term work on rural and small urban roads; they do not cover interstates or SCDOT contract work, which follow the SCDOT Standard Drawings. Flaggers: Flaggers must complete a flagger training course from an SCDOT-approved provider. Accepted: ATSSA, Carolinas AGC, ITRE (NC State), J.M. Teague, Southeastern Chapter NSC, Tri-County Technical College. (SCDOT Flagger's Handbook; SCDOT Approved Work Zone Traffic Control Training Guidelines.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-03-27; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "SCDOT Work Zone Traffic Control page (Flaggers Handbook 2026; Work Zone Safety Guidelines 2026)", "url": "https://www.scdot.org/business/workzone-traffic-control.html", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "SCDOT Flaggers Handbook 2026; Work Zone Safety Guidelines 2026", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-sd-adopt-1", "state": "SD", "tier": "core", "title": "South Dakota traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "South Dakota: an industry tracker lists the state as one that uses the national MUTCD without a state manual of its own, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Flaggers must be certified in South Dakota before flagging on a Department project (course + written test); age 18+; carry proof. How long it lasts: 2 years. (SDDOT Standard Specifications for Roads & Bridges, C. Flagging.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2026-11-04; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "SDDOT Standard Specifications for Roads & Bridges, C. Flagging; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-43/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "SDDOT Standard Specifications for Roads & Bridges, C. Flagging, as posted 2026-11-04", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: SDDOT Traffic Operations Manual (rev. 01/03/2025) says only \"current edition of the MUTCD\"; no adoption found."}},
{"lib": "field", "chunk": {"id": "tc-tn-adopt-1", "state": "TN", "tier": "core", "title": "Tennessee traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Tennessee uses the national MUTCD 11th Edition. TDOT Traffic Design memo TM 2512 (December 23, 2025) says every project must conform to the 11th Edition starting with the May 8, 2026 letting, following the formal adoption of the MUTCD, and that the MUTCD governs where TDOT's own manuals disagree until they are updated. Flaggers: Flaggers trained and certified in flagging operations by an approved program. Accepted: ATSSA, National Safety Council, TTAP, ABET-accredited university programs, or Department-approved program. (TDOT Standard Specifications (2021), Flaggers.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2023-03-20; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "TDOT Traffic Design Division memo TM 2512, MUTCD Compliance (12/23/2025)", "url": "https://www.tn.gov/content/dam/tn/tdot/traffic-engineering/sigstd/TM%202512%20Signed.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition (TDOT TM 2512)"}},
{"lib": "field", "chunk": {"id": "tc-tx-adopt-1", "state": "TX", "tier": "core", "title": "Texas traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Texas uses its own manual, the Texas MUTCD (TMUTCD). TxDOT's page says the current version is Revision 1 of the 2025 TMUTCD, effective November 18, 2026; the 2025 TMUTCD itself took effect January 18, 2026. Flaggers: Contractor designates in writing a flagger instructor who serves as flagging supervisor and trains flaggers; list of certified flaggers before work begins; TxDOT keeps a list of approved flagger courses. (TxDOT Standard Specifications, Flaggers (Item 7 section 2.6.2 as quoted).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-08-11; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "TxDOT TMUTCD page (Revision 1 of the 2025 TMUTCD); TxDOT Standard Specifications, Flaggers", "url": "https://www.txdot.gov/business/resources/traffic-design-standards/tmutcd.html", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2025 TMUTCD, Revision 1", "effective": "2026-11-18"}},
{"lib": "field", "chunk": {"id": "tc-ut-adopt-1", "state": "UT", "tier": "core", "title": "Utah traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Utah adopts a Utah MUTCD by rule R920-1. The copy of R920-1-2 read here still names the 2009 Edition, and the rule's history dates run only to June 22, 2022; adoption of the 11th Edition was not confirmed, so check with UDOT Traffic and Safety. Flaggers: Flaggers must be trained and certified before flagging in a work zone; official course by a certified instructor. How long it lasts: 3 years. Accepted: programs listed in UDOT Standard Specification 01554. (UDOT Flagger Training & Certification page; UDOT Flagger Handbook.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-11-13; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "Utah Admin. Code R920-1-2; UDOT Flagger Training & Certification page; UDOT Standard Specification 01554", "url": "https://www.law.cornell.edu/regulations/utah/Utah-Admin-Code-R920-1-2", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Utah Admin. Code R920-1-2 as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-vt-adopt-1", "state": "VT", "tier": "core", "title": "Vermont traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Vermont adopted the national MUTCD 11th Edition by state statute in the 2024 Transportation Bill, with January 18, 2026 as the compliance date (Vermont League of Cities and Towns, October 2024). The statute text itself was not confirmed here. Flaggers: 4-hour course by a certified instructor (AGC of Vermont, ATSSA or NSC instructor courses); carry proof. How long it lasts: training within the past 2 years. (VTrans Standard Specifications Section 630.04(a).) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2024-01-29; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "Vermont League of Cities and Towns, 11th Edition MUTCD article (Oct. 1, 2024)", "url": "https://vlct.org/node/3566", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition (Vermont statute, 2024)", "effective": "2026-01-18", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-va-adopt-1", "state": "VA", "tier": "core", "title": "Virginia traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Virginia uses its own manual: the Virginia MUTCD version 11.0 (2025) governs traffic control devices under VDOT, by regulation 24VAC30-315-10, effective December 17, 2025. Work zone rules are in the Virginia Work Area Protection Manual, which is part of it. Flaggers: Certified through the VDOT Flagger Certification Program, ATSSA, or another VDOT-approved program; carry a readable card. How long it lasts: VDOT flagger card 2 years; VDOT Basic/Intermediate work zone course or ATSSA classroom 4 years. Accepted: VDOT, ATSSA, VDOT-approved. (Virginia Work Area Protection Manual Section 6E.01.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2025-08-29; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "24VAC30-315-10 (eff. Dec. 17, 2025); Virginia Work Area Protection Manual Section 6E.01", "url": "https://law.lis.virginia.gov/admincode/title24/agency30/chapter315/section10", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Virginia MUTCD version 11.0 (2025)", "effective": "2025-12-17"}},
{"lib": "field", "chunk": {"id": "tc-wa-adopt-1", "state": "WA", "tier": "core", "title": "Washington traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Washington adopts the national MUTCD with state changes listed in chapter 468-95 WAC. WSDOT's page gives October 27, 2025 as the effective date for the 11th Edition in the state. Flaggers: every flagger must carry a valid state traffic control flagger card, with an expiration date no more than 3 years from issue, under WAC 296-155-305(6); the WSDOT Standard Specifications (1-10.3(1)A) say the same. Someone without a card may flag only in an emergency, until a certified flagger takes over. Cards from the reciprocity states are accepted: Oregon, Idaho and Montana. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "WSDOT MUTCD page (11th Edition effective Oct. 27, 2025); chapter 468-95 WAC; WAC 296-155-305", "url": "https://wsdot.wa.gov/engineering-standards/all-manuals-and-standards/manuals/manual-uniform-traffic-control-devices-mutcd", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "MUTCD 11th Edition with chapter 468-95 WAC modifications", "effective": "2025-10-27"}},
{"lib": "field", "chunk": {"id": "tc-wv-adopt-1", "state": "WV", "tier": "core", "title": "West Virginia traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "West Virginia: an industry tracker lists the state as one that uses the national MUTCD with a state supplement, but its adoption of the 11th Edition was not confirmed from the state DOT's own page; ask the state DOT traffic office which edition is in force. Flaggers: Flaggers must be certified by passing ATSSA training. (WVDOH Standard Specifications Section 636.11.1.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2026-08-20; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "WVDOH Standard Specifications Section 636.11.1; adoption status not confirmed", "url": "https://workzonesafety.org/practice/flagger-certification-and-training-47/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "WVDOH Standard Specifications Section 636.11.1, as posted 2026-08-20", "unconfirmed": "yes", "note": "Pass 2 (2026-11-20), still not found: Searched WVDOH specifications and 2026 publications update; no 11th Edition adoption or WV supplement found."}},
{"lib": "field", "chunk": {"id": "tc-wi-adopt-1", "state": "WI", "tier": "core", "title": "Wisconsin traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Wisconsin uses its own manual, the 11th Edition Wisconsin MUTCD (WMUTCD). FHWA found it in substantial conformance with the national 11th Edition, and WisDOT uses the date of FHWA's letter, February 24, 2026, as its effective date. Wisconsin's Part 6 differences were not read here, so check the WMUTCD Part 6 before relying on a national number. Flaggers: Since January 1, 2020 all flaggers on Wisconsin state highways must be certified (training meeting the Wisconsin Flagging Handbook). (WisDOT Standard Specifications Section 104.6.1.2.2.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2022-08-02; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "FHWA Wisconsin Division letter (Feb. 24, 2026) and WisDOT request on the 11th Edition WMUTCD", "url": "https://wisconsindot.gov/dtsdManuals/traffic-ops/manuals-and-standards/wmutcd/2023approval.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "11th Edition Wisconsin MUTCD", "effective": "2026-02-24"}},
{"lib": "field", "chunk": {"id": "tc-wy-adopt-1", "state": "WY", "tier": "core", "title": "Wyoming traffic control: which MUTCD applies and the flagger training rule", "topic": "Traffic control: which manual applies and flagger cards", "text": "Wyoming: WYDOT's rules page shows the Transportation Commission adopting the 2009 MUTCD, with a Wyoming change that lets engineering judgment or an engineering study modify a Standard where site conditions make it impossible or impractical. Adoption of the 11th Edition was not confirmed from WYDOT; ask WYDOT Traffic which edition applies. Flaggers: Complete and pass a training program approved by the State Construction Office before flagging (3-day grace in unplanned emergencies); current card on the project. How long it lasts: tested every 3 years. Accepted: Wyoming Flaggers Traffic Control Certification, ATSSA. (WYDOT Standard Specifications Section 703.4.6.) This wording is the state document as posted by the national Work Zone Safety Information Clearinghouse on 2024-08-05; confirm it in the current spec book before you rely on it. Tapers, sign spacing and cone spacing come from the national MUTCD Part 6 unless the state manual or the permit says otherwise: taper L = W x S x S / 60 at 40 mph or less and W x S at 45 mph or more. The approved traffic control plan governs.", "source": "WYDOT Standards for Uniform Traffic Control Devices page (Transportation Commission resolution)", "url": "https://dot.state.wy.us/home/administration/rules_regs/MUTCD.html", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2009 MUTCD as adopted by the Wyoming Transportation Commission", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ca-signspacing-1", "state": "CA", "tier": "core", "title": "California advance warning sign spacing by speed (CA MUTCD Table 6B-1)", "topic": "Traffic control: advance warning signs", "text": "California's Table 6B-1 in the CA MUTCD 2026 sets advance warning sign spacing by speed on urban streets, which the national table does not. Distances A, B and C are the same within each row. Urban, 25 mph or less: 100 ft. 30 mph: 150 ft. 35 mph: 200 ft. 40 mph: 250 ft. 45 mph: 300 ft. Urban, 50 mph or more: 350 ft. Rural: 500 ft. Expressway or freeway: A 1,000 ft, B 1,500 ft, C 2,640 ft. A is from the taper or point of restriction to the first sign, B from the first to the second sign, C from the second to the third. Use the posted speed limit, the off-peak 85th-percentile speed before work starts, or the expected operating speed. So three signs on a 35 mph city street sit 200 ft apart, 600 ft in all. These are recommended minimums; the encroachment permit or the approved traffic control plan can ask for more, and on State highways the Caltrans Standard Plans govern.", "source": "CA MUTCD 2026 (Caltrans, eff. Jan. 18, 2026), Table 6B-1 and footnotes; Section 6B.04", "url": "https://dot.ca.gov/-/media/dot-media/programs/safety-programs/documents/ca-mutcd/2026/2026-camutcd-2026-6b-a11y.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-ca-taper-1", "state": "CA", "tier": "core", "title": "California taper lengths by speed for a 12 ft lane (CA MUTCD Table 6B-3(CA))", "topic": "Traffic control: tapers and buffer spaces", "text": "California's CA MUTCD 2026 prints the taper lengths for a 12 ft offset in Table 6B-3(CA). Merging taper L, then shifting taper L/2, then shoulder taper L/3, in feet. 20 mph: 80, 40, 27. 25 mph: 125, 63, 42. 30 mph: 180, 90, 60. 35 mph: 245, 123, 82. 40 mph: 320, 160, 107. 45 mph: 540, 270, 180. 50 mph: 600, 300, 200. 55 mph: 660, 330, 220. 60 mph: 720, 360, 240. 65 mph: 780, 390, 260. 70 mph: 840, 420, 280. 75 mph: 900, 450, 300. Downstream taper: 50 ft, 100 ft maximum. For another width use the formula: W x S x S / 60 at 40 mph or less, W x S at 45 mph or more. S is the posted speed limit, the off-peak 85th-percentile speed before work starts, or the expected operating speed. Devices in the downstream taper and in the one-lane two-way taper go about 20 ft apart. On State highways use the Caltrans Standard Plans for traffic control systems, T9 to T27 (Section 6B.08).", "source": "CA MUTCD 2026, Section 6B.08 paras. 4, 8, 12, 14, 16; Tables 6B-3, 6B-3(CA), 6B-4", "url": "https://dot.ca.gov/-/media/dot-media/programs/safety-programs/documents/ca-mutcd/2026/2026-camutcd-2026-6b-a11y.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-ca-flagger-1", "state": "CA", "tier": "core", "title": "California flagger training rule and paddle (CA MUTCD 6D.01, 8 CCR 1599)", "topic": "Traffic control: flaggers", "text": "California does not issue a state flagger card, but training is mandatory. The CA MUTCD 2026 adds a California Standard to Section 6D.01: flaggers shall be trained in the proper fundamentals of flagging moving traffic before being assigned as flaggers. The training covers nine topics, among them flagger equipment, the layout of the work zone, signaling to stop, proceed and slow, one-way traffic control, emergency vehicles, handling emergencies, hostile drivers, and flagging alone. The trainer shall have the qualifications and experience to teach it, and the employer shall keep the training records required by its Injury and Illness Prevention Program (8 CCR 3203). The Cal/OSHA rule is Construction Safety Orders section 1599. Paddle: a 24 by 24 inch STOP/SLOW paddle may be used where more emphasis is needed and speeds are 30 mph or more; on a staff, the bottom of the paddle should be at least 6 ft above the pavement. Flags are for emergencies, at least 24 inches square. Apparel is ANSI/ISEA 107-2015 Class 2 or 3, Class 3 recommended for flaggers at night (Section 6C.05). Flagger stations shall be lit at night except in emergencies.", "source": "CA MUTCD 2026, Sections 6D.01 paras. 2-5, 6D.02 paras. 4, 5a, 6D.03, 6D.06 para. 5, 6C.05; 8 CCR 1599, 3203", "url": "https://dot.ca.gov/-/media/dot-media/programs/safety-programs/documents/ca-mutcd/2026/2026-camutcd-2026-6d-a11y.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "CA MUTCD 2026", "effective": "2026-01-18"}},
{"lib": "field", "chunk": {"id": "tc-ca-fines-1", "state": "CA", "tier": "core", "title": "California work zone fines and construction speed zones (CVC 42009, 22362)", "topic": "Traffic control: work zone speed and fines", "text": "California Vehicle Code 42009 raises the penalty for listed moving violations in a highway construction or maintenance area: a misdemeanor fine is doubled, and an infraction is charged one category higher on the uniform traffic penalty schedule. It applies only when workers are actually doing the work and traffic control devices or warning signs tell drivers the workers are there. The listed offenses include speeding, obeying traffic devices, passing, right-of-way, turning, reckless driving and DUI. Speed zones: the CA MUTCD 2026 (Section 6B.01) says a reduced construction speed limit under Vehicle Code 22362 has to be documented in writing, cannot be set below 25 mph, is posted only where the work affects traffic, and the signs are covered or removed in non-working hours unless the condition is still there. Vehicle Code 21367 lets the agency doing the work regulate traffic through it. The contractor cannot post a regulatory speed limit on its own; the agency orders it.", "source": "Cal. Veh. Code 42009(a)-(c); Veh. Code 22362, 21367; CA MUTCD 2026 Section 6B.01 paras. 19a, 20c-20p", "url": "https://california.public.law/codes/vehicle_code_section_42009", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "Cal. Veh. Code 42009 as read 2026-11-20; CA MUTCD 2026", "note": "Vehicle Code text read on a third-party mirror (california.public.law); confirm on leginfo.legislature.ca.gov."}},
{"lib": "field", "chunk": {"id": "tc-az-fines-1", "state": "AZ", "tier": "core", "title": "Arizona work zone double fines (A.R.S. 28-710) and the signs", "topic": "Traffic control: work zone speed and fines", "text": "Arizona doubles the cost of speeding in a state highway work zone when workers are present. A.R.S. 28-710: in a state highway work zone marked by traffic control devices that show where it begins and ends, a driver may not exceed the speed shown on the devices; if workers are present, the driver pays the normal civil penalty plus an additional assessment equal to it. Half of the extra goes to the state highway work zone safety fund and half to the state highway fund. Signs: the Arizona Supplement to the MUTCD (Section 6G.08) says double fine signs in state highway work zones go up only when workers are present and come down or are covered when they are not, existing speed limit signs inside the double fine area are covered, and the layout should follow the ADOT Temporary Traffic Control Design Guidelines. Leaving the double fine signs up with no crew there is not allowed under that section. City streets are not state highway work zones under this statute.", "source": "A.R.S. 28-710(A)-(D); A.R.S. 28-652; ADOT Arizona Supplement to the MUTCD 11th Edition (Jan. 2026) Section 6G.08", "url": "https://www.azleg.gov/ars/28/00710.htm", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "edition": "A.R.S. 28-710 as read 2026-11-20"}},
{"lib": "field", "chunk": {"id": "tc-nv-fines-1", "state": "NV", "tier": "core", "title": "Nevada double penalties in work zones (NRS 484B.130)", "topic": "Traffic control: work zone speed and fines", "text": "Nevada adds a second penalty, equal to the first, for speeding and other listed traffic offenses in a temporary traffic control zone (NRS 484B.130). It applies when construction, maintenance or repair workers are present, or when the road condition, such as narrowed or shifted lanes or an uneven surface, makes the violation more dangerous. The added penalty is capped at $1,000, 6 months in jail or 120 hours of community service. Signs are part of it: the agency or its contractor must put up a sign before the zone reading DOUBLE PENALTIES IN WORK ZONES, a sign at the beginning of the zone and a sign at the end. If the signs are missing the double penalty generally does not apply, unless the violation injured a worker or did $1,000 or more in property damage. Signs are not required for emergency zones or on roads posted 25 mph or less next to residential areas, and there the double penalty applies only with a worker injury or $1,000 or more in damage. So on a Nevada job, the three signs are the contractor's to set.", "source": "NRS 484B.130(1)-(6)", "url": "https://nevada.public.law/statutes/nrs_484b.130", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "NRS 484B.130 as read 2026-11-20", "note": "Read on nevada.public.law (mirror, accessed text dated May 2025); confirm on leg.state.nv.us."}},
{"lib": "field", "chunk": {"id": "tc-tx-fines-1", "state": "TX", "tier": "core", "title": "Texas work zone fines double when workers are present (Transp. Code 472.022)", "topic": "Traffic control: work zone speed and fines", "text": "Texas Transportation Code 472.022 makes it an offense to disobey a warning sign or drive around a barricade, with a fine of $1 to $200. If it happens in a construction or maintenance work zone while workers are present, and the citation says so, the fine is $2 to $400. A stretch of road only counts as a construction or maintenance work zone for this purpose if it is marked by signs that say it is a work zone, show where the zone begins and ends, and state: Fines double when workers present. Mobile operations, as the Texas MUTCD defines them, are not included. Driving around a barricade placed because water is over the road is a Class B misdemeanor. For a crew this means the begin, end and fines-double signs have to be in the setup for the higher fines to apply.", "source": "Tex. Transp. Code 472.022", "url": "https://codes.findlaw.com/tx/transportation-code/transp-sect-472-022/", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "Tex. Transp. Code 472.022, current as of Jan. 1, 2026", "note": "Read on FindLaw (current as of 2026-01-01); confirm on statutes.capitol.texas.gov."}},
{"lib": "field", "chunk": {"id": "tc-fl-fines-1", "state": "FL", "tier": "core", "title": "Florida speeding fines double in a posted construction zone (s. 318.18(3)(e))", "topic": "Traffic control: work zone speed and fines", "text": "Florida doubles the speeding fine in a posted construction zone under section 318.18(3)(e), Florida Statutes. Two conditions: the zone is posted, with the posting stating the speed limit and that fines are doubled; and construction personnel are present or operating equipment on the road or immediately next to it. The regular fines in 318.18(3)(b) are $25 for 6 to 9 mph over, $100 for 10 to 14 over, $150 for 15 to 19 over, $175 for 20 to 29 over and $250 for 30 mph or more over, so doubled they are $50, $200, $300, $350 and $500, before court costs. No crew on or beside the road means no doubling, even with the signs up. FDOT work zone layouts are in the FDOT Standard Plans, Index 102 series, and FDOT requires its Temporary Traffic Control (MOT) training for people who set up and supervise work zones on state roads; those two points were not confirmed from an FDOT page here.", "source": "s. 318.18(3)(b), (3)(e), Fla. Stat. (2025)", "url": "https://flsenate.gov/Laws/Statutes/2025/318.18", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "s. 318.18, Fla. Stat. (2025)", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-wa-flagger-1", "state": "WA", "tier": "core", "title": "Washington flagger card rule (WAC 296-155-305)", "topic": "Traffic control: flaggers", "text": "Washington requires a flagger card by state safety rule. WAC 296-155-305(6): each flagger must have in their possession a valid Washington traffic control flagger card, or a valid card from a state that has a reciprocity agreement with Washington. The card shows the training completed, the date, the instructor, the issuing state and an expiration date no more than 3 years from issue, with a photo or the words valid with photo ID. Training is based on the MUTCD. The reciprocity states named are Oregon, Idaho and Montana, and the WSDOT standard specifications (1-10.3(1)A) likewise accept cards from those states. Someone without a card may flag only in an emergency, until a certified flagger takes over. Other points in the same rule: flaggers are used only when other traffic control is not enough; the employer orients each flagger to the site (the job, equipment, traffic pattern, signals with operators, an escape route on foot); a site-specific traffic control plan is kept on site for jobs longer than one day; flaggers may not be given other duties or use a cell phone or headphones while flagging; and they get a paid 10 minute rest for each 4 hours.", "source": "WAC 296-155-305(2), (6), (7), (9); WSDOT Standard Specifications 1-10.3(1)A", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-155-305", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "edition": "WAC 296-155-305, last amended WSR 16-09-085", "effective": "2016-05-20"}},
{"lib": "field", "chunk": {"id": "tc-wa-fines-1", "state": "WA", "tier": "core", "title": "Washington speeding in a roadway construction zone: double penalty (RCW 46.61.527)", "topic": "Traffic control: work zone speed and fines", "text": "Washington doubles the penalty for speeding in a roadway construction zone. RCW 46.61.527: a roadway construction zone is an area where public employees or private contractors are doing construction, repair or maintenance work on or next to a public road. A driver may not exceed the speed shown on the traffic control devices in the zone, and a speed infraction there carries twice the usual penalty, which may not be waived, reduced or suspended. The same section creates the crime of reckless endangerment of roadway workers, a gross misdemeanor: driving in a construction zone in a way that endangers or is likely to endanger people or property, or removing, evading or intentionally striking a traffic safety or control device. A conviction brings a 60 day license suspension. Standards for the devices on state highways are set by the Secretary of Transportation. The text read here showed amendments through 2009; later changes were not confirmed.", "source": "RCW 46.61.527(1)-(5)", "url": "https://lawfilesext.leg.wa.gov/Law/RCW/RCW%20%2046%20%20TITLE/RCW%20%2046%20.%2061%20%20CHAPTER/RCW%20%2046%20.%2061%20.527.htm", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "RCW 46.61.527 as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-or-handbook-1", "state": "OR", "tier": "core", "title": "Oregon Temporary Traffic Control Handbook (OTTCH): the rules for jobs of 3 days or less", "topic": "Traffic control: which manual applies and flagger cards", "text": "Oregon's standard for short work zones is the Oregon Temporary Traffic Control Handbook, 2026 edition (January 2026), adopted through OAR 734-020-0005. It covers traffic control in place continuously for three days or less on any public road in the state. Longer jobs, or jobs more complicated than the handbook's diagrams, need a full traffic control plan. A traffic control plan is required whenever work is done on or along a public road; for short jobs the handbook diagram can be the plan. Flaggers: certified in Oregon, Washington, Idaho or Montana, at least 18 years old, retrained every three years, carrying the card (sections 3.2 and 3.3). When only flaggers are used, the distance between the Flagger signs should not be more than one mile; past that use a pilot car. Drivers should not be held longer than 20 minutes at a flagger station under normal conditions. Apparel: ANSI/ISEA 107-2015 or later, Type R, Class 2 or 3; flaggers Class 2 required and Class 3 recommended at night. Cone spacing: the posted speed in feet in a taper and twice that along the work. Cities and counties may be stricter and usually require a permit.", "source": "Oregon Temporary Traffic Control Handbook 2026 (ODOT), sections 1.1, 1.4, 2.3, 3.2, 3.3, 3.6, 3.8; OAR 734-020-0005", "url": "https://www.oregon.gov/odot/Engineering/Docs_TrafficEng/OTTCH-2026.pdf", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "summary", "edition": "OTTCH 2026 Edition, January 2026"}},
{"lib": "field", "chunk": {"id": "tc-co-fines-1", "state": "CO", "tier": "core", "title": "Colorado work zone penalties and the signs that turn them on (C.R.S. 42-4-614)", "topic": "Traffic control: work zone speed and fines", "text": "Colorado increases penalties and surcharges for listed traffic violations inside a designated maintenance, repair or construction zone (C.R.S. 42-4-614, with the amounts in 42-4-1701(4)(c)). CDOT designates the zone on a state highway; on any other road the public entity doing the work does. A zone can be designated only when work is going on or will be within four hours. Signs make the zone: one sign before the work area telling drivers that increased penalties are in effect, and one after it telling them the increased penalties no longer apply. The zone runs from the first sign to the second. The signs must meet CDOT's requirements and may be on fixed, variable or movable stands, or on a moving vehicle for work such as striping. The size of the increase was not confirmed here; it is set in section 42-4-1701. Colorado flagger notes from CDOT: flaggers must speak and understand English, and fluorescent red apparel is not allowed for flaggers.", "source": "C.R.S. 42-4-614; C.R.S. 42-4-1701(4)(c); CDOT Flagger Program industry memo (Jan. 1, 2026)", "url": "https://colorado.public.law/statutes/crs_42-4-614", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "C.R.S. 42-4-614 (2024 edition) as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ut-fines-1", "state": "UT", "tier": "core", "title": "Utah: obey the flagger, and double fines for speeding past workers (41-6a-209)", "topic": "Traffic control: work zone speed and fines", "text": "Utah Code 41-6a-209 does two things. First, it is an offense to willfully fail or refuse to obey a lawful order or direction of a flagger at a highway construction or maintenance site who is using the devices and procedures required, the same as disobeying a peace officer or a school crossing guard. Second, for speeding in a highway construction or maintenance site, the court must set the fine at no less than double the amount in the uniform recommended fine schedule, but only if workers are present at the site and the site is clearly marked with signs warning drivers of the doubled fine. Without workers there, or without the signs, the doubling does not apply. Flaggers in the state must be trained and certified before flagging, and the certification lasts three years (UDOT Flagger Training and Certification page). The section's last listed amendment is from the 2005 General Session; later changes were not confirmed.", "source": "Utah Code 41-6a-209; UDOT Flagger Training & Certification page", "url": "https://le.utah.gov/xcode/Title41/Chapter6A/C41-6a-S209_1800010118000101.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "edition": "Utah Code 41-6a-209 as read 2026-11-20", "unconfirmed": "yes"}},
{"lib": "field", "chunk": {"id": "tc-ak-ttc-1", "state": "AK", "tier": "core", "title": "Alaska work zone sign spacing, flagger paddle and flagger certification (2026 ATMS)", "topic": "Traffic control: advance warning signs", "text": "Alaska's 2026 Alaska Traffic Manual Supplement (ATMS), effective January 20, 2026, changes a few national Part 6 numbers. Advance warning sign spacing (ATMS Table 6B-1, which replaces the national table): urban low speed 100 ft between signs, urban high speed 350 ft, rural 500 ft, expressway or freeway A 1,000 ft, B 1,500 ft, C 2,640 ft. The footnote sets low speed as 40 mph or less and high speed as 45 mph or more. Flagger paddle (6D.02): at least 24 inches wide with 8 inch letters, except on local roads with a speed limit of 25 mph or less, where 18 inches with 6 inch letters is allowed. Flagger certification (6D.01): on state highways flaggers must be certified under the current Standard Specifications for Highway Construction, Section 643, Traffic Maintenance. Speed reductions in the work zone (6B.01): avoid them where practical, keep them to 10 mph or less unless restrictive features require more, and follow DOT&PF Policy and Procedure 05.05.020. The approved traffic control plan or permit governs.", "source": "2026 ATMS Rev. 0 (Alaska DOT&PF), Sections 6B.01 paras. 17-19A, 6D.01 para. 01A, 6D.02 para. 02A, Table 6B-1", "url": "https://dot.alaska.gov/stwddes/dcstraffic/assets/pdf/atm/current/2026_atm.pdf", "checked": "2026-11-20", "confidence": "medium", "kind": "summary", "license": "summary", "edition": "2026 Alaska Traffic Manual Supplement, Revision 0", "effective": "2026-01-20", "note": "Read through the WebFetch summarizer (the ATMS PDF is 580k characters); numbers match the national table pattern. Confirm in the printed ATMS before a crew sheet uses them."}}]$kb$::jsonb) with ordinality t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = t.e->'chunk'->>'id');

-- the version's row count (the Ask loader refuses a library whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';
-- drop the saved search index so workers rebuild it from the rows
delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';
delete from pb_ai.kb_index where version = 'b3e91f6c47d2';
-- checks: ords must stay 0..n-1 with no gaps, ids unique
do $chk$
declare n int; mx int; d int;
begin
  select count(*), max(ord), count(distinct chunk->>'id') into n, mx, d from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if mx <> n - 1 then raise exception 'FAIL ord gap: % rows, max ord %', n, mx; end if;
  if d <> n then raise exception 'FAIL duplicate chunk id: % ids for % rows', d, n; end if;
  if (select v.n from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2') <> n then raise exception 'FAIL kb_versions.n'; end if;
end $chk$;
commit;
